"""Camera-guided ClearFoodWaste controller. Uses only public robot client observations.
No scene state, demonstrations, policies, resets, or success queries.
Run with --worker for persistent command interface; observations/actions saved in runs.
"""
import numpy as np, json, sys, time, os
from pathlib import Path
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
from rcb_client import Robot
ROOT=Path('/app'); CAMS=['robot0_agentview_center','robot0_agentview_left','robot0_agentview_right','robot0_eye_in_hand']
ORIGINS=[([0,0,.333],0),([0,0,0],-np.pi/2),([0,-.316,0],np.pi/2),([.0825,0,0],np.pi/2),([-.0825,.384,0],-np.pi/2),([0,0,0],np.pi/2),([.088,0,0],np.pi/2)]
LIMIT_LO=np.array([-2.8973,-1.7628,-2.8973,-3.0718,-2.8973,-.0175,-2.8973]);LIMIT_HI=np.array([2.8973,1.7628,2.8973,-.0698,2.8973,3.7525,2.8973])
def fk(q):
 T=np.eye(4)
 for a,(p,rx) in zip(q,ORIGINS):
  A=np.eye(4);A[:3,3]=p;A[:3,:3]=Rotation.from_euler('x',rx).as_matrix()@Rotation.from_euler('z',a).as_matrix();T=T@A
 return T

def model(q):
 c=json.load(open(ROOT/'output/calibration.json'));F=fk(q);R=Rotation.from_rotvec(c['rot']).as_matrix();return R@(F[:3,3]+F[:3,:3]@np.array(c['tip']))+c['trans'],R@F[:3,:3]

def ik(p, rot=None, seed=None):
 if seed is None: seed=np.array(json.load(open(ROOT/'output/latest.json'))['proprio']['now'][4:11])
 def err(q):
  pp,rr=model(q);e=list((pp-p)*8)
  if rot is not None:e.extend(Rotation.from_matrix(np.array(rot)@rr.T).as_rotvec()*1.3)
  e.extend((q-seed)*.02)
  return e
 res=least_squares(err,np.clip(seed,LIMIT_LO+.001,LIMIT_HI-.001),bounds=(LIMIT_LO,LIMIT_HI),max_nfev=250)
 pp,rr=model(res.x);return res.x,pp,rr,np.linalg.norm(pp-p)

def deproject(run,cam,u,v):
 m=json.load(open(ROOT/'runs'/run/'meta.json')); K=np.array(m['cameras'][cam]['intrinsic_cv']);T=np.array(m['cameras'][cam]['cam2world_gl']);D=np.load(ROOT/'runs'/run/f'depth_{cam}.npy');D=D[-1] if D.ndim==3 else D
 z=float(D[int(v),int(u)]);v3=np.array([(u-K[0,2])*z/K[0,0],-(v-K[1,2])*z/K[1,1],-z]);return T[:3,:3]@v3+T[:3,3]

def worker():
 r=Robot();i=0
 print('READY',flush=True)
 while True:
  try: c=json.loads(input())
  except EOFError:break
  try:
   name=c.get('name',f'{i:03d}');i+=1
   if c['op']=='obs':o=r.get_obs(cameras=c.get('cams',CAMS),include_depth=True,seconds=c.get('seconds',0),video='none')
   elif c['op']=='action':
    A=np.array(c['actions']);o=r.submit('joint_position',A,cameras=c.get('cams',CAMS),include_depth=True,video='none',note=c.get('note',name))
    np.save(ROOT/'runs'/f'actions_{name}.npy',A)
   o.save(str(ROOT/'runs'/name));(ROOT/'output/latest.json').write_text(json.dumps(o.meta));print(json.dumps({'saved':name,'state':o.meta['proprio']['now'],'time_left':o.meta['time_left_s']}),flush=True)
  except Exception as e:print('ERROR '+str(e),flush=True)
if __name__=='__main__' and '--worker' in sys.argv:worker()
